const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([104.238631, 40.923221]);
  const aoi = center.buffer(50000); // 50km radius

  const date2019_start = '2019-02-01';
  const date2019_end = '2019-03-01';
  const date2020_start = '2020-02-01';
  const date2020_end = '2020-03-01';

  // 2. Data Acquisition & Check
  const pm25Band = 'particulate_matter_d_less_than_25_um_surface';

  const col2019 = ee.ImageCollection('ECMWF/CAMS/NRT')
    .select(pm25Band)
    .filterDate(date2019_start, date2019_end)
    .filterBounds(aoi);

  const col2020 = ee.ImageCollection('ECMWF/CAMS/NRT')
    .select(pm25Band)
    .filterDate(date2020_start, date2020_end)
    .filterBounds(aoi);

  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log('No data found for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate mean PM2.5 for each period
  const mean2019 = col2019.mean();
  const mean2020 = col2020.mean();

  // 4. Reduction with pixel count validation
  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 10000,
    maxPixels: 1e9
  });

  const stats2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 10000,
    maxPixels: 1e9
  });

  const pm2019 = stats2019.get(pm25Band + '_mean').getInfo();
  const count2019 = stats2019.get(pm25Band + '_count').getInfo();
  const pm2020 = stats2020.get(pm25Band + '_mean').getInfo();
  const count2020 = stats2020.get(pm25Band + '_count').getInfo();

  console.log(`2019 PM2.5: ${pm2019}, Pixels: ${count2019}`);
  console.log(`2020 PM2.5: ${pm2020}, Pixels: ${count2020}`);

  // 5. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (pm2019 === null || pm2020 === null || 
      isNaN(pm2019) || isNaN(pm2020) ||
      pm2019 < 0 || pm2020 < 0 || pm2019 > 1000 || pm2020 > 1000) {
    console.log('Invalid PM2.5 values calculated.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Comparison: Feb 2020 (${pm2020.toFixed(2)}) vs Feb 2019 (${pm2019.toFixed(2)})`);

  if (pm2020 > pm2019) {
    console.log('PM2.5 was higher in February 2020.');
    console.log('<answer>A</answer>');
  } else {
    console.log('PM2.5 was not higher in February 2020.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
